  -- Reads a team set (none = the active one).
  function BattleBayDeluxe.active_team_read(from)
    local set = from or VRFW.host.command(B.VS_SET)
    if type(set) ~= "number" or set < 0 then
      return nil, "no active team set (CMND_GET_VS_USE_TEAM_SET " .. tostring(set) .. ")"
    end
    local d = { set = set, lineup = {}, members = {}, captain = 0, tactics = {}, name = "" }
    local parts = {}
    for k = 0, B.MEMBERS - 1 do
      local has, hdl = VRFW.host.command(B.MEMBER, set, B.TEAM_TYPE, k, 0)
      if has and type(hdl) == "number" and hdl ~= 0 then
        local hasp, pos = VRFW.host.command(B.MEMBER, set, B.TEAM_TYPE, k, 1)
        if hasp and type(pos) == "number" and pos >= 0 and pos <= B.COACH_POSITION and d.members[pos] == nil then
          d.members[pos] = VRFW.ids.unsigned(hdl)
        end
        if hasp and type(pos) == "number" and pos >= 0 and pos <= B.SQUAD_LAST and d.lineup[pos] == nil then
          local card = VRFW.host.command(B.STATUS, hdl, 4)
          card = VRFW.ids.unsigned(card) or 0
          if card ~= 0 then
            d.lineup[pos] = card
            parts[#parts + 1] = string.format("%d:%.0f", pos, card)
            local hask, captain = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_CAPTAIN, hdl)
            if hask and captain == true then
              d.captain = card
            end
          end
        end
      end
    end
    if #parts == 0 then
      return nil, "the team set " .. set .. " has no players"
    end
    local hasf, formation = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_FORMATION)
    if hasf and type(formation) == "number" and formation ~= 0 then
      d.formation = formation
    end
    local hase, emblem = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_EMBLEM, 0)
    if hase and type(emblem) == "number" and emblem ~= 0 then
      d.emblem = emblem
    end
    local hasu, uniform = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_UNIFORM)
    if hasu and type(uniform) == "number" and uniform ~= 0 then
      d.uniform = uniform
    end
    local hasn, name = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_NAME)
    if hasn and type(name) == "string" then
      d.name = name
    end
    for i = 0, B.TACTICS - 1 do
      local hast, tactic = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_TACTIC, i)
      d.tactics[i] = (hast and type(tactic) == "number") and tactic or 0
    end
    d.text = table.concat(parts, ",")
    return d
  end

  function BattleBayDeluxe.active_team_sync(why)
    local d, err = BattleBayDeluxe.active_team_read()
    if not d then
      if B.read_error ~= err then
        B.read_error = err
        BattleBayDeluxe.active_team_log("not read (" .. tostring(why) .. "): " .. tostring(err))
      end
      return nil
    end
    B.read_error = nil
    local key = string.format("%s|%.0f|%d|%.0f|%.0f|%s", d.text, d.captain, d.set, d.emblem or 0, d.uniform or 0, d.name)
    if B.sent ~= key then
      local ok, done, info = pcall(funcLuaCommand, B.MIRROR, d.captain, d.text, d.set, d.emblem or 0, d.uniform or 0,
        d.name)
      if ok and done == true then
        B.sent = key
      end
      BattleBayDeluxe.active_team_log("mirror (" .. tostring(why) .. "): team set " .. d.set .. ", " .. tostring(info or done) ..
        (ok and "" or " (the scripts were busy: again next time)"))
    end
    B.data = d
    return d
  end

  -- A template as panel data (the shape of active_team_read); nil when it is empty or BetterQoL does not answer.
  function BattleBayDeluxe.template_read(t)
    local ok, captain, lineup, set, emblem, uniform, name, formation, t0, t1, t2, members = pcall(funcLuaCommand, B.T_CARD, t)
    if not ok or type(lineup) ~= "string" or lineup == "" then
      return nil
    end
    local d = { set = set or -1, template = t, lineup = {}, members = {}, captain = VRFW.ids.unsigned(captain) or 0, text = lineup,
      tactics = { [0] = t0 or 0, [1] = t1 or 0, [2] = t2 or 0 }, name = type(name) == "string" and name or "" }
    for pos, card in lineup:gmatch("(%d+):(%d+)") do
      d.lineup[tonumber(pos)] = tonumber(card)
    end
    -- every member's live character by position, the coach included (the line-up holds the 0..18 cards only)
    for pos, hdl in tostring(members or ""):gmatch("(%d+):(%d+)") do
      local p = tonumber(pos)
      if p <= B.COACH_POSITION and d.members[p] == nil then
        d.members[p] = tonumber(hdl)
      end
    end
    d.formation = (type(formation) == "number" and formation ~= 0) and formation or nil
    d.emblem = (type(emblem) == "number" and emblem ~= 0) and emblem or nil
    d.uniform = (type(uniform) == "number" and uniform ~= 0) and uniform or nil
    B.card_logged = B.card_logged or {}
    if not B.card_logged[t] then
      B.card_logged[t] = true
      BattleBayDeluxe.active_team_log(string.format("template %d: set %s, formation %s, emblem %s, kit %s, captain %s, name %q, lineup %s",
        t, tostring(d.set), VRFW.ids.hex_text(d.formation or 0), VRFW.ids.hex_text(d.emblem or 0),
        VRFW.ids.hex_text(d.uniform or 0), VRFW.ids.hex_text(d.captain), d.name, lineup))
    end
    return d
  end

  -- Whether a template can be lined up: 11 starters.
  function BattleBayDeluxe.template_fields(d)
    if d == nil then
      return false
    end
    for pos = 0, B.STARTERS - 1 do
      if d.lineup[pos] == nil then
        return false
      end
    end
    return true
  end

  -- True when BetterQoL's templates are usable in this save.
  function BattleBayDeluxe.templates_usable()
    local ok, usable = pcall(funcLuaCommand, B.T_INFO)
    return ok and usable == true
  end

  -- The templates the Personal Teams section offers, in BetterQoL's list order: each template BetterQoL lists as not
  -- empty that has a line-up, except the `skip` ones, as { template, panel data }; nil when the list is not answered.
  function BattleBayDeluxe.personal_templates(skip)
    local ok, numbers = pcall(funcLuaCommand, B.T_LIST)
    if not ok or type(numbers) ~= "string" then
      return nil
    end
    local offered = {}
    for number in numbers:gmatch("%d+") do
      local t = tonumber(number)
      local d = not skip[t] and BattleBayDeluxe.template_read(t) or nil
      if d ~= nil then
        offered[#offered + 1] = { template = t, data = d }
      end
    end
    return offered
  end

  -- Keeps the template of a saved run in a dock and points its tile at it; the templates no run plays are let go.
  function BattleBayDeluxe.personal_run_hold(why)
    B.run = nil
    funcLuaCommand(B.T_LET_GO, B.MATCH_OWNER)
    local ok, team, t = pcall(funcLuaCommand, B.TILE_RUN)
    if ok and type(team) == "number" and type(t) == "number" then
      -- the run's tile shows its template even when the dock is refused now (the next opening asks again)
      B.run = { team = team, template = t }
      local set, code = funcLuaCommand(B.T_USE, t, B.OWNER, 0)
      if type(set) == "number" and funcLuaCommand(B.TILE_PLAYS, team, set, t) == true then
        BattleBayDeluxe.active_team_log("run (" .. tostring(why) .. "): template " .. t .. " kept in team set " .. set)
      else
        BattleBayDeluxe.active_team_log("run (" .. tostring(why) .. "): template " .. t .. " not kept (code " .. tostring(code) .. ")")
      end
      return B.run
    end
    funcLuaCommand(B.T_LET_GO, B.OWNER)
    return nil
  end

  -- Mirrors the templates of the shown page onto the Personal Teams tiles; empty templates and the active one are hidden.
  -- `keep` reuses the templates listed when the section opened (a page turn), else they are listed again.
  function BattleBayDeluxe.personal_docks_sync(why, keep)
    if B.docks == nil then
      local ok, list = pcall(funcLuaCommand, B.DOCK_LIST)
      if not ok or type(list) ~= "string" then
        BattleBayDeluxe.active_team_log("no tile list (" .. tostring(why) .. "): the scripts were busy")
        return 0
      end
      B.docks = {}
      for team, set in list:gmatch("(%d+):(%d+)") do
        B.docks[#B.docks + 1] = { team = tonumber(team), set = tonumber(set) }
      end
    end
    B.dock_data, B.dock_sent, B.tile_template = {}, B.dock_sent or {}, {}
    local active_set = VRFW.host.command(B.VS_SET)
    local usable = BattleBayDeluxe.templates_usable()
    local active = usable and funcLuaCommand(B.T_OF_DOCK, active_set) or active_set
    if not keep then
      B.offered = usable and BattleBayDeluxe.personal_templates({ [active] = true, [B.run and B.run.template or 0] = true }) or nil
    end
    local offered = B.offered
    local shown = 0
    local next_entry = B.page * #B.docks
    for _, e in ipairs(B.docks) do
      local t, d
      if offered == nil then
        -- without usable templates (slot 1, story) each tile shows the dock it plays, as retail docks
        t, d = e.set, BattleBayDeluxe.active_team_read(e.set)
      elseif B.run ~= nil and B.run.team == e.team then
        t = B.run.template
        d = BattleBayDeluxe.template_read(t)
      else
        next_entry = next_entry + 1
        local entry = offered[next_entry]
        if entry ~= nil then
          t, d = entry.template, entry.data
        end
      end
      local ready = BattleBayDeluxe.template_fields(d)
      B.dock_data[e.team] = d
      B.tile_template[e.team] = (offered ~= nil and d ~= nil) and t or nil
      pcall(funcLuaCommand, B.DOCK_READY, e.team, ready and 1 or 0)
      if d ~= nil then
        local key = string.format("%d|%s|%.0f|%.0f|%.0f|%s", t, d.text, d.captain, d.emblem or 0, d.uniform or 0, d.name)
        if B.dock_sent[e.team] ~= key then
          local ok, done = pcall(funcLuaCommand, B.MIRROR, d.captain, d.text, d.set, d.emblem or 0, d.uniform or 0, d.name, e.team)
          if ok and done == true then
            B.dock_sent[e.team] = key
          end
        end
      end
      local show = d ~= nil and t ~= active
      funcLuaCommand(B.PAGE_HIDE, e.team, show and 0 or 1)
      shown = shown + (show and 1 or 0)
    end
    funcLuaCommand(B.PAGE_HIDE, B.TEAM, 0)
    BattleBayDeluxe.active_team_log("personal templates (" .. tostring(why) .. "): page " .. (B.page + 1) .. ", " .. shown ..
      " of " .. #B.docks .. " shown")
    return shown
  end

  -- Plays the template of a picked Personal Teams tile: USE puts it in a dock and the tile plays that team set.
  -- Answers false when the pick is refused (the template cannot be lined up or BetterQoL refused it).
  function BattleBayDeluxe.personal_pick(team)
    local t = B.tile_template ~= nil and B.tile_template[team] or nil
    if t == nil then
      return true
    end
    if not BattleBayDeluxe.template_fields(B.dock_data[team]) then
      BattleBayDeluxe.active_team_log("template " .. t .. " not selectable: it has no 11 starters")
      return false
    end
    local owner = (B.run ~= nil and B.run.team ~= team) and B.MATCH_OWNER or B.OWNER
    local set, code = funcLuaCommand(B.T_USE, t, owner, 0)
    if type(set) ~= "number" then
      BattleBayDeluxe.active_team_log("template " .. t .. " refused by BetterQoL (code " .. tostring(code) .. ")")
      return false
    end
    if funcLuaCommand(B.TILE_PLAYS, team, set, t) ~= true then
      BattleBayDeluxe.active_team_log("template " .. t .. ": its tile was not pointed at team set " .. set)
      return false
    end
    BattleBayDeluxe.active_team_log("template " .. t .. " picked: team set " .. set .. ", kept for " .. owner)
    return true
  end
end
